package com.example.siliguide.data.local.sqldelight

import app.cash.sqldelight.db.SqlDriver
import com.example.siliguide.data.local.SiliGuideDatabase
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class SiliGuideDatabaseManager @Inject constructor(
    private val driver: SqlDriver
) {
    // The class name generated by create("SiliGuideDatabase")
    val database: SiliGuideDatabase by lazy {
        SiliGuideDatabase.Companion(driver)
    }

    // FIX: Since all your SQL is in SiliGuide.sq, SQLDelight
    // puts everything into this one property:
    val queries = database.siliGuideQueries
}